using Microsoft.Dynamics365.LocalizationFramework;
using Microsoft.Dynamics.AX.Framework.FileManagement;
using SL = Microsoft.Dynamics365.LocalizationFramework.XppSupportLayer;
using Microsoft.Azure;
using Microsoft.WindowsAzure.Storage;
using Microsoft.WindowsAzure.Storage.File;
using Microsoft.WindowsAzure.Storage.Blob;
using Microsoft.WindowsAzure.Storage.Auth;

/// <summary>
/// MPJ_30779_PaymentPlus
/// <c>METERFileDestinationAzureStorage</c> manages the new ER destination for 'MET Azure Storage'
/// </summary>
public class METERFileDestinationAzureStorage implements ERIFileDestinationWithResult
{
    private DocuTypeId docuTypeId;
    private boolean isEncrypted;
    private boolean overwrite;

}

Method.Source:
/// <summary>
/// Creates a new instance of <C>METERFileDestinationAzureStorage</C>.
/// </summary>
/// <param name = "_docuTypeId">A document type id.</param>
public void new(DocuTypeId _docuTypeId)
{
    docuTypeId = _docuTypeId;
}

public DocuTypeId parmDocuTypeId(DocuTypeId _docuTypeId = docuTypeId)
{
    docuTypeId = _docuTypeId;
    return docuTypeId;
}

public boolean parmOverwrite(boolean _value = overwrite)
{
    overwrite = _value;
    return overwrite;
}

public boolean parmIsEncrypted(boolean _value = isEncrypted)
{
    isEncrypted = _value;
    return isEncrypted;
}

    /// <summary>
    /// Main method to save the ER file in destination
    /// </summary>
    /// <param name = "_stream">A stream to save.</param>
    /// <param name = "_filePath">A file path.</param>
    /// <returns>Saved stream.</returns>
    [Hookable(false)]
    public System.IO.Stream saveFile(System.IO.Stream _stream, str _filePath)
    {
        System.Exception exception;
        str errorMessage, message;
        boolean isSuccessful;
        DocuType docuType = DocuType::find(docuTypeId);
        if (!docuType)
        {
            throw error(strFmt("@SYS28052", docuTypeId));
        }
        if (docuType.FilePlace != DocuFilePlace::METAzureStorage)
        {
            throw error(strFmt("@MET:DocuTypeAzureStorageValidation", docuTypeId));
        }

        try
        {
            [isSuccessful, message] = METBlobStorageHelper::upload(_stream, System.IO.Path::GetFileName(_filePath), docuTypeId, isEncrypted);
            if (isSuccessful)
            {
                info(message);
            }
        }
        
        catch (Exception::Error)
        {            
            errorMessage = Global::METGetErrorAndCLR();
            throw error(errorMessage);

        }        
        
        return _stream;
    }

[Hookable(false)]
public System.IO.Stream newFileStream(str _filePath)
{
    return new System.IO.MemoryStream();
}

/// <summary>
/// Finalizes files processing.
/// </summary>
[Hookable(false)]
public void finalize()
{
}

/// <summary>
///   Saves file in destination and retrieves the operation result.
///   Method is used for the import process when moving file to a different folder
/// </summary>
/// <param name = "_stream">A stream to save.</param>
/// <param name = "_filePath">A file path.</param>
/// <returns>The operation result.</returns>
[Hookable(false)]
public ERFileSaveResult TrySaveFile(System.IO.Stream _stream, str _filePath)
{
    System.Exception exception;
    str errorMessage, message;
    boolean isSuccessful;
    DocuType docuType = DocuType::find(docuTypeId);
    if (!docuType)
    {
        errorMessage = strFmt("@SYS28052", docuTypeId);
    }
    if (docuType.FilePlace != DocuFilePlace::METAzureStorage)
    {
        errorMessage = strFmt("@MET:DocuTypeAzureStorageValidation", docuTypeId);
    }
    if (!errorMessage)
    {
        try
        {
            [isSuccessful, message] = METBlobStorageHelper::upload(_stream, System.IO.Path::GetFileName(_filePath), docuTypeId, isEncrypted);
        }
        catch (Exception::Error)
        {
            errorMessage = Global::METGetErrorAndCLR();
        }
    }
    return isSuccessful ? ERFileSaveResult::Success(message) : ERFileSaveResult::Fail(errorMessage, message);
}
